function runCmd(cmd, handler) {
  var req = http.request({
    socketPath: socketPath,
    path: '/' + cmd,
  }, function(res) {
    var body = '';
    res.on('data', function(data) { body = body + data; });
    res.on('end', function() {
      handler(JSON.parse(body));
    });
  });
  req.end();
}

